public enum CellKind { Open, Wall, Door, Window, Fence, Car, Tree, Crate }
public struct Cell { public CellKind Kind; public sbyte Height; public short Hp; public bool DoorOpen; public byte Floor; }
public sealed class BattleMap {
  public int W, H, Revision; public Cell[] Cells;
  public bool[] ExtractMask; public List<(int x,int y)> Deploy, Spawn;
  public List<Container> Containers;
  public int Idx(int x, int y) => y * W + x;
}
public record CellDef(string Id, bool Walk, int Cover, bool BlocksSight, int Hp, float MoveCost, string ArtKey);

public enum BattlePhase { Setup, Deploy, PlayerTurn, EnemyTurn, Over }
public enum Side { Player, Enemy, Third }
public sealed class Battle {
  public BattlePhase Phase; public int Turn; public BattleMap Map;
  public List<Unit> Units; public Queue<int> EnemyQueue; public Rng Rng;
  public BattleOutcome? Outcome; public List<BattleEvent> Events;
}
public sealed class Unit { public int Id; public Side Side; public int X, Y, Hp, MaxHp, Ap; public float Mob; public bool Aware, Down, Extracted; }

public readonly record struct ReachResult(float[] Cost, int[] Prev, int Start);
public enum WalkerProfile { Person, Dead, Runner }
public static class Pathfinder {
  public static ReachResult Reachable(Battle b, Unit u, float maxCost);
  public static List<(int x,int y)> PathTo(in ReachResult r, int x, int y);
}
public sealed class DistanceField { public float[] Dist; public int Revision; public WalkerProfile Profile; }

public enum CoverLevel { None = 0, Half = 1, Full = 2 }
public readonly record struct CoverResult(CoverLevel Level, bool Flanked);
public sealed record ShotOdds(int Chance, int Crit, int DmgMin, int DmgMax,
  IReadOnlyList<(string Label, int Delta)> Parts);
public static class Los { public static bool Clear(BattleMap m, int x0, int y0, int x1, int y1); }
public static class HitChance { public static ShotOdds Shot(Battle b, Unit a, Unit t); }

public interface IBattleCommand { int UnitId { get; } string? Refusal(Battle b); void Execute(Battle b); }
public sealed record MoveCmd(int UnitId, int X, int Y) : IBattleCommand { ... }
public sealed record ShootCmd(int UnitId, int TargetId) : IBattleCommand { ... }
public sealed record SearchCmd(int UnitId, int ContainerId) : IBattleCommand { ... }
public abstract record BattleEvent(int Turn);
public sealed record ShotFired(int Turn, int A, int T, bool Hit, int Dmg, bool Crit) : BattleEvent(Turn);

public sealed record DeadTypeDef(
  string Id, string Name, int HpBase, int HpPerPower, float HpMult,
  float Mob, int Sight, float Hearing,
  int MeleeAimBase, int MeleeAimPerPower, int DmgMin, int DmgMax,
  float Armor, float Strength, string BrainId, string ArtKey);
public sealed record DeadMix(string Id, IReadOnlyDictionary<string, float> Weights);

public enum Awareness { Dormant, Unaware, Investigating, Aware }
public interface IUnitBrain { void TakeTurn(Battle b, Unit u); }
public sealed class DeadMind { public Awareness State; public (int x,int y)? Lure; public int LureTurns; public int Pod; }
public readonly record struct Noise(int X, int Y, float Radius, Side Source, string Why);
public sealed class BrainRegistry { public IUnitBrain this[string id] => _map[id]; readonly Dictionary<string, IUnitBrain> _map = new(); }

public enum Outcome { Victory, Defeat, Retreat }
public sealed record EnemySpec(string Kind, int Count, int Power, string MixId);
public sealed record BattleSetup(int TileId, int? PartyId, int? BaseId, EnemySpec Enemy,
  Side? Ambush, bool CanRetreat, string HandlerKey, JsonObject Context);
public sealed record BattleResult(Outcome Outcome, int EnemiesKilled, int EnemiesLeft,
  IReadOnlyList<int> Hurt, IReadOnlyList<int> Dead, int AmmoUsed, Loot Loot, int Turns);
public interface IBattleHandler { void Apply(World w, BattleResult r, BattleSetup s); }
